```verilog
`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg  [7:0] d;
    wire [7:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .d(d),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // 3. Stimulus & self-checking
    integer errors = 0;
    integer i;

    initial begin
        // Initialize signals
        clk = 0;
        d   = 8'h00;
        #12; // Wait past the first rising edge

        // Apply a concise loop of meaningful test vectors (5-20 vectors)
        for (i = 0; i < 10; i = i + 1) begin
            @(posedge clk);
            // Apply new stimulus slightly after edge or setup before
            d = $random;

            // Wait for propagation to check against expected behavior (1 cycle latency)
            #1;
            // On the next positive edge, q should update to the current d
            @(posedge clk);
            #1; // Small delay for output to settle

            if (q !== d) begin
                $display("Time %0t: Mismatch! d = 0%h, q = 0%h", $time, d, q);
                errors = errors + 1;
            end
        end

        // Final status report
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
```

